// Original authored subtypes. Alignments describe relevance, never whole-position coverage.
const deepFreeze = (value) => {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    Object.values(value).forEach(deepFreeze);
    Object.freeze(value);
  }
  return value;
};
const n = (seed, modulus, offset = 0) => offset + seed % modulus;
const fmt = (value) => String(value).replace('.', ',');
const round = (value, places = 6) => Number(value.toFixed(places));
const fraction = (a, b) => `${a}/${b}`;
const answer = (id, label, expected, answerUnit) => ({ id, label, kind: 'number', check: 'numeric', expected: String(expected), ...(answerUnit ? { answerUnit } : {}), maxPoints: 1 });
const template = (familyId, id, title, build, version = 1) => ({
  id,
  build(seed) {
    if (!Number.isInteger(seed) || seed < 0 || seed > 2147483647) throw new RangeError('seed должен быть целым от 0 до 2147483647');
    const content = build(seed);
    return deepFreeze({ id: `${familyId}:v${version}:${id}:${seed}`, familyId, version, templateId: id, seed, title, ...content });
  },
});
const lesson = (meaning, notation, conditions, why, prompt, solution, pitfalls, probePrompt, probeAnswer, explanation, links) => ({
  meaning, notation, conditions, why, example: { prompt, solution }, pitfalls,
  probe: { prompt: probePrompt, answer: String(probeAnswer), kind: 'number', explanation }, links,
});
const family = (id, title, group, scope, exclusions, align2026, align2027, prerequisites, skills, learning, templates, version = 1) => ({
  id, title, group, version, scope, exclusions,
  prerequisites: prerequisites.map(([familyId, role]) => ({ familyId, role })),
  alignments: { '2026': align2026, '2027': align2027 }, skills, lesson: learning,
  templates: templates.map(([key, build]) => template(id, key, title, build, version)),
});
